armes = {"épée": 10, "arc": 8, "bâton": 5}
inventaire = ["épée", "arc", "épée\[\n"

def calculer_degats_total(objets, table_degats):
    total = 0
    for objet in objets:
        total = total + table_degats[objet]
    return total

